import{_ as a,c as s,o as t,ag as i}from"./chunks/framework.B-aGGnuW.js";const k=JSON.parse('{"title":"Live setup","description":"","frontmatter":{},"headers":[],"relativePath":"installation/live-setup.md","filePath":"installation/live-setup.md","lastUpdated":1792149212000}'),n={name:"installation/live-setup.md"};function l(o,e,p,h,r,d){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="live-setup" tabindex="-1">Live setup <a class="header-anchor" href="#live-setup" aria-label="Permalink to &quot;Live setup&quot;">​</a></h1><p>Download a current ISO from the <a href="https://archlinux.org/download/" target="_blank" rel="noreferrer">official download page</a> and follow its signature verification instructions before booting it.</p><h2 id="set-the-keyboard-layout" tabindex="-1">Set the keyboard layout <a class="header-anchor" href="#set-the-keyboard-layout" aria-label="Permalink to &quot;Set the keyboard layout&quot;">​</a></h2><p>The console defaults to US. List layouts, then load yours; this example uses German:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">localectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list-keymaps</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">loadkeys</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> de-latin1</span></span></code></pre></div><p>Use the same layout when entering encryption passwords and configuring the installed system.</p><h2 id="connect-to-the-internet" tabindex="-1">Connect to the internet <a class="header-anchor" href="#connect-to-the-internet" aria-label="Permalink to &quot;Connect to the internet&quot;">​</a></h2><p>Wired networking normally connects automatically. For Wi-Fi, enter <code>iwctl</code>, then run the following commands inside its prompt, replacing <code>wlan0</code> and the network name:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>device list</span></span>
<span class="line"><span>station wlan0 scan</span></span>
<span class="line"><span>station wlan0 get-networks</span></span>
<span class="line"><span>station wlan0 connect &quot;Your network name&quot;</span></span>
<span class="line"><span>exit</span></span></code></pre></div><p>Check connectivity and synchronize the clock:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ping</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> archlinux.org</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">timedatectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set-ntp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span></code></pre></div><h2 id="check-the-firmware-mode" tabindex="-1">Check the firmware mode <a class="header-anchor" href="#check-the-firmware-mode" aria-label="Permalink to &quot;Check the firmware mode&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/firmware/efi/efivars</span></span></code></pre></div><p>If this directory exists, the ISO booted in UEFI mode. Otherwise it booted in BIOS mode. For a UEFI installation, reboot and select the UEFI entry for your USB drive if necessary.</p>`,14)])])}const u=a(n,[["render",l]]);export{k as __pageData,u as default};
